for _id, _m in BREAKS.items():
    for _p in SPECS[_id]["panels"]:
        _p["bubbles"] = [(b[0], b[1], b[2], _m[b[1]]) if b[1] in _m else tuple(b) for b in _p["bubbles"]]
    for _k, _v in _m.items():
        assert _v.replace("\n", "") == _k
    _n = sum(1 for _p in SPECS[_id]["panels"] for b in _p["bubbles"] if len(b) > 3)
    assert _n == len(_m), (_id, _n, len(_m))

